import { Component } from '@angular/core';
import { RouterModule } from '@angular/router';
import { CartItem, CartService } from 'src/app/services/cart.service';

@Component({
  selector: 'app-cart',
  templateUrl: './cart.component.html',
  styleUrls: ['./cart.component.scss']
})
export class CartComponent {
 cartItems: CartItem[] = [];   // will store items from backend
  router: any;

  constructor(private cartService: CartService,router:RouterModule) {}

  ngOnInit(): void {
    this.loadCart();
  }

  loadCart() {
    this.cartService.getCartItems().subscribe(items => {
      this.cartItems = items;
    });
  }

  removeFromCart(id: number) {
    this.cartService.removeCartItem(id).subscribe(() => {
      this.loadCart(); // refresh after removal
    });

  }
  toOrderDetail(){
this.router.navigate(['/order-details']);
  }
}
<div class="cart-container">
  <h2>Your Cart</h2>

  <div *ngIf="cartItems.length === 0" class="empty-cart">
    <p>No items in cart.</p>
  </div>

  <div class="product-grid">
    <div *ngFor="let item of cartItems" class="product-card">
      <h3>{{ item.product.title }}</h3>
      <p><strong>Price:</strong> ₹{{ item.product.price }}</p>
      <p><strong>Quantity:</strong> {{ item.quantity }}</p>
      <button (click)="removeFromCart(item.id)" class="remove-btn">Remove</button>
    </div>
  </div>
  <button (click)="toOrderDetail">Checkout</button> 
</div>
